import { useId } from 'react'
import { heroTitle } from './heroTitleData'

// Hero headline "From evidence to impact": Poppins ExtraBold letter shapes with a
// Gilgongo-style zigzag strip cut into the first stroke of each letter.
// The shapes are generated by gen/hero_svg.py (heroTitleData.js) so the pattern
// follows every letter. Size it with font-size on the parent: 1em = font size.
function Line({ data, fill, gradient }) {
  const id = useId().replace(/:/g, '')
  const { d, cuts, width, top, height } = data
  return (
    <svg viewBox={`0 ${top} ${width} ${height}`} aria-hidden="true" focusable="false"
      style={{ height: `${height / 1000}em`, width: `${width / 1000}em` }} className="inline-block overflow-visible">
      <defs>
        <mask id={`m${id}`} maskUnits="userSpaceOnUse" x={-50} y={top} width={width + 100} height={height}>
          <rect x={-50} y={top} width={width + 100} height={height} fill="#fff" />
          <path d={cuts} fill="#000" />
        </mask>
        {gradient && (
          <linearGradient id={`g${id}`} gradientUnits="userSpaceOnUse" x1="0" y1="0" x2={width} y2="0">
            <stop offset="0" stopColor="var(--color-tangerine)" />
            <stop offset="1" stopColor="var(--color-teal)" />
          </linearGradient>
        )}
      </defs>
      <path d={d} fill={gradient ? `url(#g${id})` : fill} mask={`url(#m${id})`} />
    </svg>
  )
}

export default function HeroTitle({ className = '' }) {
  return (
    <h1 className={className}>
      <span className="sr-only">From evidence to impact</span>
      <span className="flex flex-wrap items-center justify-center gap-x-[0.22em] gap-y-[0.08em]">
        <Line data={heroTitle.line1} fill="var(--color-ink)" />
        <Line data={heroTitle.line2} gradient />
      </span>
    </h1>
  )
}
